                    if ((($c = strnatcasecmp($va, $vb)) < 0 || ($c === 0 && $ia > $ib))) {
                        $a[$low] = $vb;
                        $ix[$low] = $ib;
                        $a[$mid] = $va;
                        $ix[$mid] = $ia;
                        $vb = $va;
                        $ib = $ia;
                    }
                }
                $p = $vb;
                $pi = $ib;

                // Hoare partition; key(low) and key(high) are the sentinels.
                $i = $low + 1;
                $j = $high - 1;
                while (true) {
                    while ((($c = strnatcasecmp(($x = $a[$i]), $p)) > 0 || ($c === 0 && $ix[$i] < $pi))) {
