        // Merge passes, ping-pong between ($a, $ax) and ($b, $bx); the first write to $b separates it.
        $b = $a;
        $bx = $ax;
        for ($width = 8; $width < $n; $width <<= 1) {
            for ($low = 0; $low < $n; $low += 2 * $width) {
                $mid = $low + $width;
                $end = $mid + $width < $n ? $mid + $width : $n;
                if ($mid < $n) {
                    $c = $cmp($a[$mid - 1], $a[$mid]);
                    if (!\is_int($c)) {
                        $c = self::result($c);
                    }
                }
                // A lone run, or two runs already in order: copy.
                if ($mid >= $n || $c <= 0) {
                    for ($k = $low; $k < $end; ++$k) {
                        $b[$k] = $a[$k];
                        $bx[$k] = $ax[$k];
                    }
                    continue;
                }
                $i = $low;
                $j = $mid;
                $k = $low;
                $l = $a[$i];
                $r = $a[$j];
                while (true) {
                    // The left element wins ties: that is the stability.
                    $c = $cmp($l, $r);
                    if (!\is_int($c)) {
                        $c = self::result($c);
                    }
                    if ($c <= 0) {
                        $b[$k] = $l;
                        $bx[$k] = $ax[$i];
                        ++$k;
                        if (++$i === $mid) {
                            break;
                        }
                        $l = $a[$i];
                    } else {
                        $b[$k] = $r;
                        $bx[$k] = $ax[$j];
                        ++$k;
                        if (++$j === $end) {
                            break;
                        }
                        $r = $a[$j];
                    }
