                    $b[$k] = $a[$i];
                    $bx[$k] = $ax[$i];
                    ++$i;
                    ++$k;
                }
                while ($j < $end) {
                    $b[$k] = $a[$j];
                    $bx[$k] = $ax[$j];
                    ++$j;
                    ++$k;
                }
            }
            $t = $a;
            $a = $b;
            $b = $t;
            $t = $ax;
            $ax = $bx;
            $bx = $t;
            $t = null;
        }

        $arr = $a;
